#!/usr/bin/env node
// scaffold-date-picker.js — v78 ship a shadcn-style DatePicker built on
// react-day-picker + Popover. Single source for any date Input field
// rendered by scaffold-form-from-entity.
//
// Adds react-day-picker + date-fns to deps.
// Idempotent. Marker: '// Generated by scaffold-date-picker'.
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--target') out.target = argv[++i];
    else if (a === '--force') out.force = true;
    else if (a === '--dry-run') out.dryRun = true;
  }
  if (!out.target) { console.error('Usage: scaffold-date-picker --target FRONTEND_DIR'); process.exit(1); }
  return out;
}

function marker() { return '// Generated by scaffold-date-picker — DO NOT EDIT BY HAND. Re-run to refresh.'; }

function writeIfManaged(file, content, force, dryRun) {
  if (fs.existsSync(file)) {
    var existing = fs.readFileSync(file, 'utf-8');
    if (!/Generated by scaffold-date-picker/.test(existing) && !force) return { written: false, reason: 'exists-handauthored' };
    if (existing === content) return { written: false, reason: 'unchanged' };
  }
  if (dryRun) return { written: false, reason: 'dry-run' };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  return { written: true };
}

function ensureDep(pkgPath, deps, dryRun) {
  if (!fs.existsSync(pkgPath)) return { changed: false, reason: 'no-package-json' };
  var pkg; try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8')); } catch (_) { return { changed: false, reason: 'parse-error' }; }
  pkg.dependencies = pkg.dependencies || {};
  var added = [];
  Object.keys(deps).forEach(function (k) {
    if (!pkg.dependencies[k] && !(pkg.devDependencies || {})[k]) { pkg.dependencies[k] = deps[k]; added.push(k); }
  });
  if (!added.length) return { changed: false, reason: 'already-present' };
  if (dryRun) return { changed: false, reason: 'dry-run', added: added };
  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
  return { changed: true, added: added };
}

var DATE_PICKER = [
  marker(),
  "import { useState } from 'react';",
  "import { format } from 'date-fns';",
  "import { Calendar as CalendarIcon } from 'lucide-react';",
  "import { DayPicker } from 'react-day-picker';",
  "import 'react-day-picker/style.css';",
  "import { Button } from '~/components/ui/button';",
  "import { Popover, PopoverContent, PopoverTrigger } from '~/components/ui/popover';",
  "import { cn } from '~/lib/utils';",
  '',
  'export interface DatePickerProps {',
  '  value?: Date | string;',
  '  onChange?: (date: Date | undefined) => void;',
  '  placeholder?: string;',
  '  className?: string;',
  '  testId?: string;',
  '}',
  '',
  "export function DatePicker({ value, onChange, placeholder = 'Pick a date', className, testId = 'date-picker' }: DatePickerProps) {",
  '  const initial = value ? (value instanceof Date ? value : new Date(value)) : undefined;',
  '  const [open, setOpen] = useState(false);',
  '  return (',
  '    <Popover open={open} onOpenChange={setOpen}>',
  '      <PopoverTrigger asChild>',
  '        <Button',
  '          type="button"',
  '          variant="outline"',
  "          className={cn('w-full justify-start text-left font-normal', !initial && 'text-muted-foreground', className)}",
  '          data-testid={`${testId}-trigger`}',
  '        >',
  '          <CalendarIcon className="mr-2 h-4 w-4" />',
  "          {initial ? format(initial, 'PPP') : placeholder}",
  '        </Button>',
  '      </PopoverTrigger>',
  '      <PopoverContent className="w-auto p-2" align="start" data-testid={`${testId}-popover`}>',
  '        <DayPicker',
  '          mode="single"',
  '          selected={initial}',
  '          onSelect={(d) => { onChange?.(d); setOpen(false); }}',
  '        />',
  '      </PopoverContent>',
  '    </Popover>',
  '  );',
  '}',
  '',
].join('\n');

function main() {
  var args = parseArgs(process.argv);
  var r = writeIfManaged(path.join(args.target, 'app/components/ui/date-picker.tsx'), DATE_PICKER, args.force, args.dryRun);
  var d = ensureDep(path.join(args.target, 'package.json'), { 'react-day-picker': '^9.0.0', 'date-fns': '^3.0.0' }, args.dryRun);
  console.log('scaffold-date-picker: date-picker.tsx=' + (r.written ? 'wrote' : r.reason) + ' deps=' + (d.changed ? '+' + d.added.join(',') : d.reason));
}

main();
